const input = $input.first().json;
const MEM_URL = ($env && $env.MEMORY_URL) || 'http://forge-memory:4002';
const MEM_TOKEN = ($env && $env.MEMORY_TOKEN) || '';
const MISTRAL_KEY = ($env && ($env.MISTRAL_API_KEY || $env.MISTRAL_API_KEY_2)) || '';
// V2.1 : embeddings avec repli local. Mistral (si clé valide) sinon vecteur lexical local
// 512 dims (hachage FNV de mots + bigrammes). Les dimensions diffèrent (1024 vs 512) :
// le service mémoire ne compare que des vecteurs de même dimension -> aucun mélange.
function localEmbed(t) {
  const D = 512, v = new Array(D).fill(0);
  const w = String(t).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]{2,}/g) || [];
  const h = s => { let x = 2166136261; for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 16777619); } return x >>> 0; };
  const add = (s, wt) => { const x = h(s); v[x % D] += ((x >>> 9) & 1 ? 1 : -1) * wt; };
  w.forEach((x, i) => { add(x, 1); if (i) add(w[i - 1] + ' ' + x, 0.5); });
  return v;
}
async function embed(helpers, t) {
  if (MISTRAL_KEY) {
    try {
      const emb = await helpers.httpRequest({ method: 'POST', url: 'https://api.mistral.ai/v1/embeddings', headers: { 'Authorization': 'Bearer ' + MISTRAL_KEY, 'Content-Type': 'application/json' }, body: { model: 'mistral-embed', input: [t] }, json: true, timeout: 15000 });
      const vec = emb && emb.data && emb.data[0] && emb.data[0].embedding;
      if (Array.isArray(vec)) return { vector: vec, embedder: 'mistral-embed' };
    } catch (e) { /* clé absente/révoquée (401) ou quota : repli local */ }
  }
  return { vector: localEmbed(t), embedder: 'local-hash-512' };
}
const text = String(input.text || '').slice(0, 8000);
const base = { task_id: input.task_id, operation: 'WRITE', category: input.kind, project: input.project, timestamp: new Date().toISOString() };
if (!text) return [{ json: Object.assign({}, base, { status: 'STORED', stored: false, message: 'Texte vide — rien à mémoriser' }) }];
try {
  const _e = await embed(this.helpers, text);
  const vector = _e.vector;
  const stored = await this.helpers.httpRequest({ method: 'POST', url: MEM_URL + '/store', headers: { 'Content-Type': 'application/json', 'X-Memory-Token': MEM_TOKEN }, body: { kind: input.kind, project: input.project, text: text, vector: vector, meta: Object.assign({}, input.meta || {}, { embedder: _e.embedder }) }, json: true, timeout: 15000 });
  return [{ json: Object.assign({}, base, { status: 'STORED', stored: true, entry_id: stored && stored.id, dim: stored && stored.dim, embedder: _e.embedder, message: 'Entrée mémorisée (' + input.kind + '/' + input.project + ', ' + _e.embedder + ')' }) }];
} catch (e) {
  // Non bloquant : la mémoire est advisory, elle ne fait jamais échouer le pipeline.
  return [{ json: Object.assign({}, base, { status: 'STORED', stored: false, degraded: true, message: 'Mémoire indisponible (' + (e && e.message) + ') — ignoré (non bloquant)' }) }];
}

