const input = $input.first().json;
const isSuccess = input.status === 'STORED' || input.status === 'RETRIEVED';

return [{
  json: {
    success: isSuccess,
    agent: "Agent Knowledge/Memory", _version: '2.2',
    task_id: input.task_id,
